/* ══════════════ CALCUL ══════════════ */
function calculer(message) {
  const m = message.replace(/,/g, '.');
  let expr = null;
  const q = m.match(/(?:combien font?|calcule|calculer|resultat de|resous)\s*:?\s*([\d\s+\-*/^().,%]+)/i);
  if (q) expr = q[1];
  else if (/^[\s\d+\-*/^().,%]+[=?]?\s*$/.test(m) && /[+\-*/^]/.test(m) && /\d/.test(m)) expr = m;
  if (!expr) return null;

  const clean = expr.replace(/[=?]/g, '').replace(/\^/g, '**').replace(/×/g, '*').replace(/÷/g, '/').trim();
  if (!clean || !/^[\d\s+\-*/*().]+$/.test(clean)) return null;
  try {
    const val = Function(`"use strict";return (${clean})`)();
    if (typeof val !== 'number' || !isFinite(val)) return null;
    const joli = Number.isInteger(val) ? val.toLocaleString('fr-FR') : val.toLocaleString('fr-FR', { maximumFractionDigits: 6 });
    return `**${expr.replace(/[=?]/g, '').trim()} = ${joli}** 🧮`;
  } catch { return null; }
}

/* ══════════════ CONVERSATION LOCALE ══════════════ */
function repondre(message, history = []) {
  let m = norm(message);
  // recolle les élisions tapées avec une espace : "c est quoi l adn"
  m = m.replace(/\bqu\s+est\s+ce\s+que?\b/g, "qu'est-ce que");
  m = m.replace(/\b([cdjlmnst])\s+(?=[aeiouyh])/g, '$1');
  const brut = message.trim();
  const premier = history.length < 2;

  // calcul
  const calc = calculer(brut);
  if (calc) return calc;

  // salutations
  if (/^(bonjour|salut|coucou|hello|bonsoir|hey|yo|slt|cc)\b[\s,!.]*$/i.test(m))
    return premier
      ? `Bonjour ! 🦊 Je suis **Fox IA**.\n\nPose-moi une question, ou demande-moi de créer une **image**, une **vidéo** ou un **site web** — je m'en occupe directement ici.`
      : `Oui ? 🦊 Je t'écoute.`;
  if (/^(bonjour|salut|coucou|hello|bonsoir|hey)\b/i.test(m)) {
    const suite = brut.replace(/^(bonjour|salut|coucou|hello|bonsoir|hey|yo)[\s,!.]*/i, '').trim();
    if (suite.length > 2) return repondre(suite, history);
  }
  if (/(^|\b)(ca va|comment (tu )?vas?|comment vas.tu|comment ca va|comment allez.vous|tu vas bien|vous allez bien|quoi de neuf|ca roule|la forme)\b/i.test(m))
    return `Très bien, merci ! 🦊 Et toi ?\n\nQu'est-ce que je peux faire pour toi aujourd'hui ?`;
  if (/^(merci|thanks|nickel|super|parfait|genial|top|cool|excellent)\b/i.test(m))
    return `Avec plaisir ! 🦊 N'hésite pas si tu as besoin d'autre chose.`;
  if (/^(au revoir|bye|a\+|a plus tard|a plus\s*$|bonne nuit|bonne journee|bonne soiree)/i.test(m.trim()))
    return `À bientôt ! 🦊 Tes créations restent dans ta galerie.`;
  if (/^(oui|non|ok|d'accord|daccord|ouais|yep)\b[\s.!]*$/i.test(m))
    return `👍 Dis-moi ce que tu veux faire — une question, une image, une vidéo, un site ?`;
  if (/^(j'ai une question|jai une question|une question|je peux te demander|puis.je te demander|question)/i.test(m))
    return `Bien sûr, je t'écoute ! 🦊`;

  // identité
  if (/(qui es.tu|ton nom|tu es qui|tu t'appelles|presente.toi|c'est quoi fox ia)/i.test(m))
    return `Je suis **Fox IA** 🦊, ton assistant créatif.\n\nJe discute avec toi, je réponds à tes questions, et surtout je **crée** :\n\n• 🎨 des **images 3D** jusqu'en 4K\n• 🎬 des **vidéos** animées\n• 🌐 des **sites web** complets\n\nTout se passe ici, dans la conversation. Demande-moi simplement !`;
  if (/(que sais.tu faire|tu sais faire quoi|tes capacites|tu peux faire quoi|a quoi tu sers|tes fonctionnalites)/i.test(m))
    return `Voici ce que je sais faire 🦊\n\n**Créer** — dis-le-moi en langage normal :\n• *« génère une image d'un renard dans une forêt néon »*\n• *« crée une vidéo d'un survol de ville futuriste »*\n• *« fais-moi un site pour un restaurant à Pau »*\n\n**Répondre** — questions de culture générale, sciences, histoire, calculs, explications…\n\n**Discuter** — tout simplement.\n\nEssaie !`;

  // aide / site
  if (/(aide|help|comment ca marche|comment faire|tuto|explique.{0,10}le site)/i.test(m))
    return `**Comment m'utiliser** 🦊\n\nÉcris-moi naturellement, comme à quelqu'un :\n\n| Tu écris | Je fais |\n|---|---|\n| *« génère une image de… »* | Une image 3D apparaît ici |\n| *« crée une vidéo de… »* | Une animation apparaît ici |\n| *« fais un site pour… »* | Un site web complet |\n| *« c'est quoi la photosynthèse ? »* | Je réponds |\n\nTes créations sont conservées dans la **Galerie**, et le bouton **Support** en bas te met en relation avec l'administrateur.`;
  if (/(bug|probleme|marche pas|fonctionne pas|erreur|signaler|plante|bloque)/i.test(m))
    return `Désolé pour ce souci 😕\n\nClique sur **🛟 Support** en bas à droite : ton message part à l'administrateur avec un numéro de suivi, et tu verras sa réponse dans « Mes tickets ».\n\nTu peux aussi me décrire le problème, je vais essayer de t'aider.`;
  if (/(mot de passe|connexion|me connecter|mon compte)/i.test(m) && !/(fort|securise|solide|robuste|bon mot de passe)/i.test(m))
    return `Pour ton compte 🔑\n\n• **Mot de passe oublié** → sur la page de connexion, lien *« Mot de passe oublié ? »*\n• **Le changer** → clique sur ton pseudo en haut à droite → *Changer mon mot de passe*`;
  if (/(gratuit|payant|prix|combien ca coute|abonnement|tarif)/i.test(m))
    return `Tout est **gratuit** 🦊 Pas de limite, pas d'abonnement, pas de carte bancaire.`;

  // base de connaissances
  for (const [re, rep] of SAVOIR) {
    if (re.test(m) || re.test(brut)) return typeof rep === 'function' ? rep() : rep;
  }

  // question ouverte
  const question = /\?/.test(brut)
    || /^(qui|que |qu'|quoi|quel|quelle|quels|quelles|comment|pourquoi|ou |où|quand|combien|est.ce|c'est quoi|cest quoi|peux|peut|sais|connais|explique|dis.moi|parle|raconte|donne|definis)/i.test(m);

  if (question)
    return `Bonne question ! 🦊\n\nJe dois être franc : je tourne actuellement sur mon **moteur local**, spécialisé dans la création visuelle. Ma culture générale est réelle mais limitée — je ne saurai pas répondre à tout.\n\n**Ce que je fais très bien :**\n• Générer une **image 3D** — *« génère une image d'un renard de cristal »*\n• Créer une **vidéo** — *« fais une vidéo d'un survol de ville »*\n• Construire un **site web** — *« crée un site pour un restaurant »*\n• Calculer, expliquer les bases en sciences, histoire, géo, informatique\n\n💡 *Pour une culture générale illimitée, l'administrateur peut brancher un modèle externe en ajoutant une clé API — je deviens alors aussi complet que ChatGPT.*`;

  // par défaut
  return `Je t'écoute 🦊\n\nSi tu veux que je **crée** quelque chose, dis-le-moi simplement :\n• *« génère une image de ${brut.slice(0, 40)}… »*\n• *« crée une vidéo de… »*\n• *« fais un site pour… »*\n\nOu pose-moi une question, j'y répondrai de mon mieux !`;
}

module.exports = { moderer, detecter, repondre, calculer, norm };

