app.post('/api/auth/register', wrap(async (req, res) => {
  let { pseudo, email, password } = req.body || {};
  pseudo = (pseudo || '').trim(); email = (email || '').trim().toLowerCase();
  if (!/^[a-zA-Z0-9_\-. ]{3,24}$/.test(pseudo)) return res.status(400).json({ error: 'Pseudo : 3 à 24 caractères (lettres, chiffres, _ - .)' });
  if (!/^\S+@\S+\.\S+$/.test(email)) return res.status(400).json({ error: 'Email invalide' });
  if (!password || password.length < 6) return res.status(400).json({ error: 'Mot de passe : 6 caractères minimum' });
  const first = await isFirst();
  if (!first && (await getSetting('signups_open')) !== '1') return res.status(403).json({ error: 'Les inscriptions sont fermées' });
  if (await q.get(`SELECT 1 AS x FROM users WHERE ${CI('pseudo')}=${CI('?')}`, [pseudo])) return res.status(409).json({ error: 'Ce pseudo est déjà pris' });
  if (await q.get('SELECT 1 AS x FROM users WHERE email=?', [email])) return res.status(409).json({ error: 'Cet email a déjà un compte' });
  const u = await createUser({ pseudo, email, password });
  setCookie(res, sign(u));
  res.json({ user: u, firstAdmin: u.role === 'admin' });
}));

app.post('/api/auth/login', wrap(async (req, res) => {
  const { identifier, password } = req.body || {};
  const raw = (identifier || '').trim();
  const u = await q.get(`SELECT * FROM users WHERE email=? OR ${CI('pseudo')}=${CI('?')}`, [raw.toLowerCase(), raw]);
  if (!u || !u.password_hash || !bcrypt.compareSync(password || '', u.password_hash))
    return res.status(401).json({ error: 'Identifiants incorrects' });
  if (u.banned) return res.status(403).json({ error: 'Compte suspendu' });
  setCookie(res, sign(u));
  await log('login', u.pseudo);
  res.json({ user: { id: u.id, pseudo: u.pseudo, email: u.email, role: u.role, avatar: u.avatar, credits: u.credits } });
}));

app.post('/api/auth/google', wrap(async (req, res) => {
  const { credential, pseudo } = req.body || {};
  if (!credential) return res.status(400).json({ error: 'Jeton Google manquant' });
  const r = await fetch(`https://oauth2.googleapis.com/tokeninfo?id_token=${encodeURIComponent(credential)}`);
  const p = await r.json();
  if (!p.email) return res.status(401).json({ error: 'Jeton Google invalide' });
  if (GOOGLE_CLIENT_ID && p.aud !== GOOGLE_CLIENT_ID) return res.status(401).json({ error: 'Jeton non destiné à ce site' });
  const email = p.email.toLowerCase();
  let u = await q.get('SELECT id,pseudo,email,role,avatar,banned,credits FROM users WHERE email=?', [email]);
  if (!u) {
    if (!(await isFirst()) && (await getSetting('signups_open')) !== '1') return res.status(403).json({ error: 'Les inscriptions sont fermées' });
    const base = (pseudo || p.name || email.split('@')[0]).replace(/[^a-zA-Z0-9_\-. ]/g, '').slice(0, 20) || 'Renard';
    let candidate = base, i = 1;
    while (await q.get(`SELECT 1 AS x FROM users WHERE ${CI('pseudo')}=${CI('?')}`, [candidate])) candidate = `${base}${++i}`;
    u = await createUser({ pseudo: candidate, email, provider: 'google', avatar: p.picture || null });
  }
  if (u.banned) return res.status(403).json({ error: 'Compte suspendu' });
  setCookie(res, sign(u));
  res.json({ user: u, firstAdmin: u.role === 'admin' });
}));

