// 1) demander un lien de réinitialisation
app.post('/api/auth/forgot', wrap(async (req, res) => {
  const email = (req.body?.email || '').trim().toLowerCase();
  if (!/^\S+@\S+\.\S+$/.test(email)) return res.status(400).json({ error: 'Email invalide' });

  const u = await q.get('SELECT id,pseudo,email,provider FROM users WHERE email=?', [email]);
  // réponse identique dans tous les cas : on ne révèle pas si le compte existe
  const generic = { ok: true, message: "Si un compte existe avec cet email, un lien de réinitialisation vient d'être envoyé." };

  if (!u) { await log('forgot_unknown', email, 'warn'); return res.json(generic); }
  if (u.provider === 'google') {
    return res.json({ ok: true, google: true, message: "Ce compte utilise la connexion Google : reconnecte-toi avec le bouton Google, il n'y a pas de mot de passe à réinitialiser." });
  }

  const token = crypto.randomBytes(32).toString('hex');
  const hash = crypto.createHash('sha256').update(token).digest('hex');
  const exp = new Date(Date.now() + 60 * 60 * 1000).toISOString(); // 1 heure
  await q.run('UPDATE users SET reset_token=?, reset_expires=? WHERE id=?', [hash, exp, u.id]);

  const base = process.env.PUBLIC_URL || `${req.protocol}://${req.get('host')}`;
  const link = `${base}/?reset=${token}`;
  const sent = await mailer.sendReset(u.email, u.pseudo, link);
  await log('forgot', `${u.pseudo} — email ${sent.sent ? 'envoyé' : 'non configuré'}`);

  // Si aucun service d'email n'est configuré, on renvoie le lien directement
  // (utile en local et tant que l'admin n'a pas branché son SMTP).
  if (!sent.sent) return res.json({ ...generic, devLink: link, mailMissing: true });
  res.json(generic);
}));

// 2) vérifier la validité d'un jeton
app.get('/api/auth/reset/:token', wrap(async (req, res) => {
  const hash = crypto.createHash('sha256').update(req.params.token).digest('hex');
  const u = await q.get('SELECT id,pseudo,reset_expires FROM users WHERE reset_token=?', [hash]);
  if (!u || !u.reset_expires || new Date(u.reset_expires) < new Date())
    return res.status(400).json({ error: 'Lien invalide ou expiré. Demande un nouveau lien.' });
  res.json({ ok: true, pseudo: u.pseudo });
}));

// 3) définir le nouveau mot de passe
app.post('/api/auth/reset', wrap(async (req, res) => {
  const { token, password } = req.body || {};
  if (!password || password.length < 6) return res.status(400).json({ error: 'Mot de passe : 6 caractères minimum' });
  const hash = crypto.createHash('sha256').update(token || '').digest('hex');
  const u = await q.get('SELECT id,pseudo,email,role,avatar,credits,reset_expires FROM users WHERE reset_token=?', [hash]);
  if (!u || !u.reset_expires || new Date(u.reset_expires) < new Date())
    return res.status(400).json({ error: 'Lien invalide ou expiré. Demande un nouveau lien.' });
  await q.run('UPDATE users SET password_hash=?, reset_token=NULL, reset_expires=NULL WHERE id=?', [bcrypt.hashSync(password, 10), u.id]);
  await log('reset_done', u.pseudo);
  setCookie(res, sign(u));
  res.json({ ok: true, user: { id: u.id, pseudo: u.pseudo, email: u.email, role: u.role, avatar: u.avatar, credits: u.credits } });
}));

// 4) changer son mot de passe en étant connecté
app.post('/api/auth/change-password', auth, wrap(async (req, res) => {
  const { current, password } = req.body || {};
  if (!password || password.length < 6) return res.status(400).json({ error: 'Nouveau mot de passe : 6 caractères minimum' });
  const u = await q.get('SELECT * FROM users WHERE id=?', [req.user.id]);
  if (u.password_hash && !bcrypt.compareSync(current || '', u.password_hash))
    return res.status(401).json({ error: 'Mot de passe actuel incorrect' });
  await q.run('UPDATE users SET password_hash=? WHERE id=?', [bcrypt.hashSync(password, 10), u.id]);
  await log('password_change', u.pseudo);
  res.json({ ok: true });
}));

/* ---------------- fabriques (partagées API + chat) ---------------- */
const RESOL = { hd: [1920, 1080], '2k': [2560, 1440], '4k': [3840, 2160], square: [2048, 2048], portrait: [1620, 2880] };

async function faireImage(user, prompt, resolution) {
  const [W, H] = RESOL[resolution] || RESOL['4k'];
  const { svg, meta } = renderSVG(prompt, { width: W, height: H });
  const stamp = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const png = toPng(svg, Math.min(W, 1920));
  let file;
  if (png) { file = `img_${stamp}.png`; await saveFile(file, png, 'image/png'); meta.format = 'PNG'; }
  else     { file = `img_${stamp}.svg`; await saveFile(file, svg, 'image/svg+xml'); meta.format = 'SVG'; }
  const info = await q.run('INSERT INTO creations(user_id,type,prompt,file,meta) VALUES(?,?,?,?,?)',
    [user.id, 'image', prompt, file, JSON.stringify(meta)]);
  await log('image', `${user.pseudo}: ${prompt.slice(0, 60)}`);
  return { id: info.lastInsertRowid, url: `/gen/${file}`, meta };
}

async function faireVideo(user, prompt, duration) {
  duration = Math.min(30, Math.max(3, Number(duration) || 9));
  const scenes = Math.min(6, Math.max(2, Math.round(duration / 3)));
  const frames = [];
  for (let i = 0; i < scenes; i++) {
    const { svg } = renderSVG(`${prompt} [scene ${i + 1}]`, { width: 1920, height: 1080 });
    const stamp = `${Date.now()}_${i}_${Math.random().toString(36).slice(2, 6)}`;
    const png = toPng(svg, 1280);
    let f;
    if (png) { f = `vid_${stamp}.png`; await saveFile(f, png, 'image/png'); }
    else     { f = `vid_${stamp}.svg`; await saveFile(f, svg, 'image/svg+xml'); }
    frames.push(`/gen/${f}`);
  }
  const meta = { duration, scenes, fps: 30, resolution: '1920×1080', frames };
  const info = await q.run('INSERT INTO creations(user_id,type,prompt,file,meta) VALUES(?,?,?,?,?)',
    [user.id, 'video', prompt, frames[0], JSON.stringify(meta)]);
  await log('video', `${user.pseudo}: ${prompt.slice(0, 60)}`);
  return { id: info.lastInsertRowid, frames, meta };
}

async function faireSite(user, prompt) {
  const { html, meta } = generateSite(prompt);
  const file = `site_${Date.now()}_${Math.random().toString(36).slice(2, 8)}.html`;
  await saveFile(file, html, 'text/html; charset=utf-8');
  const info = await q.run('INSERT INTO creations(user_id,type,prompt,file,meta) VALUES(?,?,?,?,?)',
    [user.id, 'website', prompt, file, JSON.stringify(meta)]);
  await log('website', `${user.pseudo}: ${prompt.slice(0, 60)}`);
  return { id: info.lastInsertRowid, url: `/gen/${file}`, html, meta };
}

/* ---------------- chat ---------------- */
app.post('/api/chat', auth, wrap(async (req, res) => {
  const msg = (req.body?.message || '').trim();
  if (!msg) return res.status(400).json({ error: 'Message vide' });

  const hist = (await q.all('SELECT role,content FROM messages WHERE user_id=? ORDER BY id DESC LIMIT 12', [req.user.id])).reverse();
  await q.run('INSERT INTO messages(user_id,role,content) VALUES(?,?,?)', [req.user.id, 'user', msg]);

  const enregistrer = async (texte) => {
    await q.run('INSERT INTO messages(user_id,role,content) VALUES(?,?,?)', [req.user.id, 'assistant', texte]);
  };

  // 1) modération
  const refus = brain.moderer(msg);
  if (refus) {
    await enregistrer(refus);
    await log('moderation', `${req.user.pseudo}: ${msg.slice(0, 60)}`, 'warn');
    return res.json({ reply: refus, kind: 'refus' });
  }

  // 2) demande de création ?
  const intention = brain.detecter(msg);
  if (intention) {
    try {
      if (intention.type === 'image') {
        const r = await faireImage(req.user, intention.prompt, intention.resolution);
        const texte = `Voilà ton image ! 🎨\n\n**${intention.prompt}**\n\n*${r.meta.resolution} · palette ${r.meta.palette}${(r.meta.effects || []).length ? ' · ' + r.meta.effects.join(', ') : ''}*`;
        await enregistrer(texte);
        return res.json({ reply: texte, kind: 'image', image: r.url, meta: r.meta, prompt: intention.prompt });
      }
      if (intention.type === 'video') {
        const r = await faireVideo(req.user, intention.prompt, intention.duration);
        const texte = `Ta vidéo est prête ! 🎬\n\n**${intention.prompt}**\n\n*${r.meta.scenes} scènes · ${r.meta.duration} s · ${r.meta.resolution}*`;
        await enregistrer(texte);
        return res.json({ reply: texte, kind: 'video', frames: r.frames, meta: r.meta, prompt: intention.prompt });
      }
      if (intention.type === 'website') {
        const r = await faireSite(req.user, intention.prompt);
        const texte = `Ton site est en ligne ! 🌐\n\n**${r.meta.name}** — ${r.meta.type}${r.meta.city ? ' à ' + r.meta.city : ''}\n\n*Responsive, prêt à télécharger.*`;
        await enregistrer(texte);
        return res.json({ reply: texte, kind: 'website', url: r.url, html: r.html, meta: r.meta, prompt: intention.prompt });
      }
    } catch (e) {
      console.error('creation chat:', e);
      const texte = `Aïe, la création a échoué : ${e.message}\n\nRéessaie en reformulant ta demande ?`;
      await enregistrer(texte);
      return res.json({ reply: texte, kind: 'erreur' });
    }
  }

  // 3) conversation
  const out = await ai.chat(hist, msg);
  const texte = (out.engine === 'connected' && out.text) ? out.text : brain.repondre(msg, hist);
  await enregistrer(texte);
  res.json({ reply: texte, kind: 'texte', engine: out.text ? 'connected' : 'local', provider: out.provider || null });
}));
app.get('/api/chat/history', auth, wrap(async (req, res) => {
  const msgs = await q.all('SELECT id,role,content,created_at FROM messages WHERE user_id=? ORDER BY id ASC LIMIT 200', [req.user.id]);
  // on rattache chaque création au message assistant qui l'annonce
  const creas = await q.all('SELECT type,prompt,file,meta,created_at FROM creations WHERE user_id=? ORDER BY id ASC', [req.user.id]);
  const restantes = creas.map(c => ({ ...c, meta: JSON.parse(c.meta || '{}') }));
  for (const m of msgs) {
    if (m.role !== 'assistant') continue;
    let kind = null;
    if (/Voilà ton image/i.test(m.content)) kind = 'image';
    else if (/Ta vidéo est prête/i.test(m.content)) kind = 'video';
    else if (/Ton site est en ligne/i.test(m.content)) kind = 'website';
    if (!kind) continue;
    const i = restantes.findIndex(c => c.type === kind);
    if (i === -1) continue;
    const c = restantes.splice(i, 1)[0];
    m.kind = kind;
    m.meta = c.meta;
    m.prompt = c.prompt;
    if (kind === 'image') m.image = `/gen/${c.file}`;
    if (kind === 'video') m.frames = c.meta.frames || [`/gen/${c.file}`];
    if (kind === 'website') m.url = `/gen/${c.file}`;
  }
  res.json({ messages: msgs });
}));
